"kind": "propose",
"summary": "Disk space exhaustion in prior revision caused failure, but new revision's logs missing. Rollback to revision 1 to resolve.",
"hypotheses": [
  {
    "root_cause_class": "storage_full",
    "summary": "Prior revision's cache directory full, but new revision's logs missing",
    "supporting": ["ev-container_logs_tail", "ev-pod_states"],
    "contradicting": ["ev-rollout_history"],
    "missing": ["container_logs_tail"],
    "status": "open"
