  {
    "root_cause_class": "configuration_change",
    "summary": "No config changes detected, but disk space issue persisted",
    "supporting": ["ev-referenced_config"],
    "contradicting": ["ev-rollout_history"],
    "missing": ["container_logs_tail"],
    "status": "open"
  }
],
"proposal": {
  "capability": "deployment.rollback-to-revision",
  "target": {
    "group": "apps",
    "kind": "Deployment",
    "namespace": "shop",
    "name": "checkout",
    "uid": "uid-deployment-checkout"
  },
  "params": {
    "revision": 1
  },
  "expected_effect": "Revert to revision 1 which had available disk space",
  "rationale": "Prior revision had disk space issue, new revision's logs missing but failure onset after rollout. Rollback resolves storage exhaustion.",
  "cited_evidence_ids": ["ev-container_logs_tail", "ev-rollout_history", "ev-pod_states", "ev-referenced_config"],
  "cited_predicates": ["rollout_recent", "failure_onset_after_rollout", "prior_revision_was_healthy", "gitops_managed", "config_changed_before_failure"]
}
}
